11	/** cp04: optional email; if present it must be unique across owners (409). */
12	@Tag("cp04")
13	class Cp04Tests extends AcceptanceBase {
14	
15		@Test
16		void coreRejectsDuplicateEmail() throws Exception {
17			String email = uniqueEmail();
18			ObjectNode a = ownerNode();
19			a.put("email", email);
20			createOwnerOk(a);
21			ObjectNode b = ownerNode(); // everything else distinct
22			b.put("email", email);
23			createOwner(b).andExpect(status().isConflict());
24		}
25	
26		@Test
