	}

	@Test
	void functionalityStoresEmail() throws Exception {
		String email = uniqueEmail();
		ObjectNode a = ownerNode();
		a.put("email", email);
		int id = createOwnerOk(a);
		getOwner(id).andExpect(jsonPath("$.email").value(email));
	}
}

